{
  "tables": [
    {
      "table": "marts.dim_sku",
      "description": "One row per SKU with its units and VAT rate."
    },
    {
      "table": "marts.dim_store",
      "description": "One row per store, with its POS sync state at the snapshot."
    },
    {
      "table": "marts.fct_goods_received",
      "description": "Stock received by each store, one row per batch, from suppliers or from other stores. Includes the opening stock received before the sales window."
    },
    {
      "table": "marts.fct_inventory_batch",
      "description": "Stock at the snapshot, one row per batch, in base units. On-hand still includes stock reserved for transfers in transit and expired stock that waits for the monthly write-off."
    },
    {
      "table": "marts.fct_returns",
      "description": "One row per returned item, with the return date and the original sale date when known."
    },
    {
      "table": "marts.fct_sales",
      "description": "One row per sales line from both POS vendors, retries removed, base units, with and without VAT."
    },
    {
      "table": "marts.fct_transfers",
      "description": "Store to store transfers in base units."
    },
    {
      "table": "marts.metricflow_time_spine",
      "description": "One row per day for MetricFlow's cumulative windows and time offsets."
    }
  ]
}

{
  "table": "marts.fct_inventory_batch",
  "columns": [
    {
      "name": "batch_id",
      "type": "VARCHAR",
      "description": "ERP batch id."
    },
    {
      "name": "store_code",
      "type": "VARCHAR",
      "description": "Store holding the batch."
    },
    {
      "name": "sku_code",
      "type": "VARCHAR",
      "description": "ERP item number."
    },
    {
      "name": "lot_no",
      "type": "VARCHAR",
      "description": "Supplier lot number."
    },
    {
      "name": "received_on",
      "type": "DATE",
      "description": "Date the batch arrived at this store."
    },
    {
      "name": "expires_on",
      "type": "DATE",
      "description": "Expiry date of the lot."
    },
    {
      "name": "days_to_expiry",
      "type": "BIGINT",
      "description": "Days from the snapshot date to expiry. Negative when already expired."
    },
    {
      "name": "source_type",
      "type": "VARCHAR",
      "description": "purchase_order or transfer."
    },
    {
      "name": "source_doc",
      "type": "VARCHAR",
      "description": "Purchase order or transfer number."
    },
    {
      "name": "on_hand_qty_base",
      "type": "INTEGER",
      "description": "Quantity on hand at the snapshot, base units."
    },
    {
      "name": "unit_cost_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Cost of one base unit from this batch, VND, VAT excluded."
    },
    {
      "name": "on_hand_value_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "on_hand_qty_base times unit_cost_excl_vat."
    },
    {
      "name": "snapshot_date",
      "type": "DATE",
      "description": "Date the stock position refers to."
    }
  ]
}

{
  "table": "marts.fct_sales",
  "columns": [
    {
      "name": "sales_line_id",
      "type": "VARCHAR",
      "description": "Vendor, receipt and line number joined."
    },
    {
      "name": "pos_vendor",
      "type": "VARCHAR",
      "description": "POS vendor, A or B."
    },
    {
      "name": "receipt_no",
      "type": "VARCHAR",
      "description": "Receipt number. Not unique per SKU, a receipt can hold the same SKU twice."
    },
    {
      "name": "line_no",
      "type": "INTEGER",
      "description": "Line number within the receipt."
    },
    {
      "name": "store_code",
      "type": "VARCHAR",
      "description": "Store code."
    },
    {
      "name": "sku_code",
      "type": "VARCHAR",
      "description": "ERP item number."
    },
    {
      "name": "business_date",
      "type": "DATE",
      "description": "Local date of the sale."
    },
    {
      "name": "sold_at",
      "type": "TIMESTAMP",
      "description": "Local time of the sale."
    },
    {
      "name": "uom_code",
      "type": "VARCHAR",
      "description": "Unit sold."
    },
    {
      "name": "qty",
      "type": "INTEGER",
      "description": "Quantity in uom_code."
    },
    {
      "name": "qty_base",
      "type": "INTEGER",
      "description": "Quantity in base units."
    },
    {
      "name": "vat_rate",
      "type": "DECIMAL(5,4)",
      "description": "VAT rate as a fraction."
    },
    {
      "name": "unit_price_incl_vat",
      "type": "BIGINT",
      "description": "Shelf price of one uom_code, VAT included."
    },
    {
      "name": "gross_incl_vat",
      "type": "BIGINT",
      "description": "Before discount, VAT included."
    },
    {
      "name": "discount_incl_vat",
      "type": "BIGINT",
      "description": "Discount, VAT included."
    },
    {
      "name": "amount_incl_vat",
      "type": "BIGINT",
      "description": "Paid, VAT included."
    },
    {
      "name": "gross_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Before discount, VAT excluded."
    },
    {
      "name": "discount_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Discount, VAT excluded."
    },
    {
      "name": "amount_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Paid, VAT excluded."
    },
    {
      "name": "unit_cost_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Weighted average cost of one base unit of the SKU at this store (DR-008)."
    },
    {
      "name": "cogs_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Cost of goods sold for the line, qty_base times unit_cost_excl_vat."
    }
  ]
}

{
  "table": "marts.dim_store",
  "columns": [
    {
      "name": "store_code",
      "type": "VARCHAR",
      "description": "Store code, for example NW001."
    },
    {
      "name": "store_name",
      "type": "VARCHAR",
      "description": "Store name."
    },
    {
      "name": "district_code",
      "type": "VARCHAR",
      "description": "District the store belongs to."
    },
    {
      "name": "district_name",
      "type": "VARCHAR",
      "description": "District name."
    },
    {
      "name": "opened_on",
      "type": "DATE",
      "description": "Date the store opened. Sell-through answers use it to flag new stores (DR-011)."
    },
    {
      "name": "days_open",
      "type": "BIGINT",
      "description": "Days between opening and the snapshot date."
    },
    {
      "name": "is_newly_opened",
      "type": "BOOLEAN",
      "description": "Opened in the 31 days before the snapshot."
    },
    {
      "name": "is_open_24h",
      "type": "BOOLEAN",
      "description": "Open around the clock."
    },
    {
      "name": "pos_vendor",
      "type": "VARCHAR",
      "description": "POS vendor, A or B."
    },
    {
      "name": "last_synced_at",
      "type": "TIMESTAMP",
      "description": "Last successful POS sync, local time."
    },
    {
      "name": "last_sync_attempt_at",
      "type": "TIMESTAMP",
      "description": "Last sync attempt, local time."
    },
    {
      "name": "last_sync_error",
      "type": "VARCHAR",
      "description": "Error of the last attempt, null when it worked."
    },
    {
      "name": "pos_data_through",
      "type": "DATE",
      "description": "Last business day whose sales have reached the warehouse. Answers use it to name lagging stores (DR-004)."
    },
    {
      "name": "pos_lag_days",
      "type": "BIGINT",
      "description": "Business days of sales still missing at the snapshot. 0 for a store synced through the day before."
    },
    {
      "name": "is_pos_sync_lagging",
      "type": "BOOLEAN",
      "description": "True when any day of sales is missing. Answers that include such a store must say so (DR-004)."
    }
  ]
}

{
  "query": "select (select sum(on_hand_qty_base) from marts.fct_inventory_batch) onhand, (select sum(on_hand_qty_base) from marts.fct_inventory_batch where days_to_expiry>=0) unexp, (select max(snapshot_date) from marts.fct_inventory_batch) snap, (select min(business_date) from marts.fct_sales) mn, (select max(business_date) from marts.fct_sales) mx, (select sum(qty_base) from marts.fct_sales where business_date>=date '2026-08-16') s30, (select count(*) from marts.dim_store where is_pos_sync_lagging) lag, (select count(*) from marts.dim_store where is_newly_opened) newst"
}

{
  "query": "select sum(i.q)/ (s.q/30.0) d_all, 1241412/(s.q/30.0) d_unexp from (select sum(on_hand_qty_base) q from marts.fct_inventory_batch) i, (select sum(qty_base) q from marts.fct_sales where business_date between date '2026-08-16' and date '2026-09-14') s group by s.q"
}

{
  "value": 25.94,
  "replacement_metric": null,
  "caveats": [
    "On-hand still includes stock reserved for transfers in transit and expired stock that waits for the monthly write-off."
  ],
  "explanation": "Total on-hand base units at the 2026-09-15 snapshot (1,241,900) divided by average daily base-unit sales over the last 30 days, 2026-08-16 to 2026-09-14 (1,436,255 / 30). Excluding expired stock gives about 25.93, so the result barely changes."
}
